import{_ as e}from"./chunks/settings-gamepad.pc.en.CHL43-MX.js";import{_ as o,o as a,c as s,a5 as n}from"./chunks/framework.BjM_ivYE.js";const g=JSON.parse('{"title":"Joystick does nothing","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/joystick-not-working.md","filePath":"manual/troubleshooting/joystick-not-working.md","lastUpdated":1790653560000}'),r={name:"manual/troubleshooting/joystick-not-working.md"};function i(d,t,h,c,l,p){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="joystick-does-nothing" tabindex="-1">Joystick does nothing <a class="header-anchor" href="#joystick-does-nothing" aria-label="Permalink to &quot;Joystick does nothing&quot;">​</a></h1><p>Buttons such as sit and stand work, but moving the sticks does not move the robot. Usually either <strong>control is held elsewhere</strong>, or the app never picked up the gamepad.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks {#first-checks}&quot;">​</a></h2><p>Open <strong>App settings → Gamepad</strong>. The status line at the top says exactly where you are.</p><p><img src="'+e+'" alt="Gamepad settings"></p><table tabindex="0"><thead><tr><th>Status line</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><code>Connected</code> + device name</td><td>The pad is being read</td><td>Go to <a href="#ownership">Ownership</a> below</td></tr><tr><td><code>No gamepad connected — using virtual joystick</code></td><td>The pad was not picked up</td><td>See <a href="#not-detected">Pad not detected</a> below</td></tr></tbody></table><p>If <code>Active profile:</code> names the wrong device, the stick layout is off and controls behave oddly — build a profile for your device with the <code>Mapping Wizard</code> in <strong>App settings → Gamepad</strong> (<a href="/RBQ/manual/gui/developer-mode.html">developer mode</a> required).</p><h2 id="not-detected" tabindex="-1">The pad is not detected <a class="header-anchor" href="#not-detected" aria-label="Permalink to &quot;The pad is not detected {#not-detected}&quot;">​</a></h2><ul><li><strong>Press a button once.</strong> For privacy reasons, browser and desktop builds <strong>only expose a device after a button press</strong>. Moving the sticks is not enough — this is the most common false alarm.</li><li><strong>Reconnect over USB or Bluetooth.</strong> On connection the app picks the device up immediately and hides the virtual joysticks.</li><li><strong>Check the joystick mode.</strong> With <code>Joystick mode</code> set to <code>Virtual joystick</code>, the screen keeps the virtual sticks even with a pad attached. Set it back to <code>Auto</code>. The same choice is in the <code>CONTROL INPUT</code> popover on the left card of the control home.</li><li><strong>Steam Deck</strong> must be launched in <strong>gaming mode</strong> (or through the Steam client) for the built-in pad to be visible to the app. Launched directly from desktop mode, the pad is emulated as mouse and keyboard and the app never sees it.</li></ul><h2 id="ownership" tabindex="-1">The on-screen input moves but the robot does not <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;The on-screen input moves but the robot does not {#ownership}&quot;">​</a></h2><p><strong>Cause:</strong> Another device holds ownership. The robot accepts input from one device at a time.</p><p><strong>Fix:</strong> When another device holds it, after about a second the app covers the screen with the <code>다른 컨트롤러가 제어 중입니다</code> overlay (another controller is in control) — press <strong><code>제어권 가져오기</code></strong> (take control) to take it over. If no overlay appeared, tap the status chip in the top bar and look at the <strong>Ownership</strong> row of <strong>Overall system status</strong>: <code>Take ▸</code> means this device is not the owner.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>With <code>External control (SLAM/SDK)</code> enabled in <strong>App settings → Gamepad</strong>, the robot follows an external program and ignores joystick input. The status chip in the top bar then shows <code>SLAM</code>. (The setting is visible in <a href="/RBQ/manual/gui/developer-mode">developer mode</a> only.)</p></div></div><h2 id="input-timeout" tabindex="-1">The robot stops mid-manoeuvre <a class="header-anchor" href="#input-timeout" aria-label="Permalink to &quot;The robot stops mid-manoeuvre {#input-timeout}&quot;">​</a></h2><p><strong>Cause:</strong> If no joystick input arrives for <strong>more than one second</strong>, the robot zeroes every control input as a safety measure. A brief wireless dropout stops the robot where it stands.</p><p><strong>Fix:</strong> Move closer to the robot and keep metal structures and walls out of the path.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>This is a safety feature, not a fault. It exists so the robot does not keep moving after the control signal is lost.</p></div></div><h2 id="buttons" tabindex="-1">The sticks work but the buttons do not <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;The sticks work but the buttons do not {#buttons}&quot;">​</a></h2><p>By default the app forwards only the sticks and <strong>L1 · R1</strong> to the robot. The other buttons are left out on purpose so a stray press cannot trigger a robot action — this is not a fault.</p><p>To attach actions to buttons, use <code>Button mapping</code> in <strong>App settings → Gamepad</strong>, or enable <code>Send all buttons</code> in <a href="/RBQ/manual/gui/developer-mode.html">developer mode</a>. See <a href="/RBQ/manual/gui/gamepad.html">Gamepad</a> for the details.</p><h2 id="stair-mode" tabindex="-1">It only fails in stair mode <a class="header-anchor" href="#stair-mode" aria-label="Permalink to &quot;It only fails in stair mode {#stair-mode}&quot;">​</a></h2><p><strong>Cause:</strong> Stair mode runs on camera data. With no camera image, the joystick can appear dead.</p><p><strong>Fix:</strong> First check that the video is coming through — see <a href="/RBQ/manual/troubleshooting/no-camera-view.html">No camera view</a>.</p><p>If the video is fine and only stair mode fails, see <a href="/RBQ/manual/troubleshooting/stair-mode-not-moving.html">Stair mode does not move</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Check whether anything appears in <strong><a href="/RBQ/manual/gui/logs.html#real-time">Logs → Real Time</a></strong> while you operate, and tell us what the status line in <strong>App settings → Gamepad</strong> said.</p><p><strong>→ <a href="/RBQ/manual/support/">Support</a></strong></p>',27)])])}const b=o(r,[["render",i]]);export{g as __pageData,b as default};
